package main

import (
	"context"
	"fmt"
	"time"

	"github.com/anyproto/anytype-heart/pb"
	"github.com/anyproto/anytype-heart/pb/service"
	"github.com/gogo/protobuf/types"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// openSpaceRPC opens a space via gRPC so we can create objects in it
func (c *AnyTypeClient) openSpaceRPC(ctx context.Context, spaceID string) error {
	fmt.Printf("[%s] gRPC: Opening workspace/space %s...\n", time.Now().Format(time.RFC3339), spaceID)

	// Create gRPC client stub
	client := service.NewClientCommandsClient(c.conn)

	// Add authentication to context
	ctx = c.withAuth(ctx)

	// Create request
	req := &pb.RpcWorkspaceOpenRequest{
		SpaceId: spaceID,
	}

	// Call WorkspaceOpen RPC
	resp, err := client.WorkspaceOpen(ctx, req)
	if err != nil {
		return c.handleGRPCError(err)
	}

	// Check response error
	if resp.Error != nil && resp.Error.Code != pb.RpcWorkspaceOpenResponseError_NULL {
		return fmt.Errorf("WorkspaceOpen failed: %s (%s)", resp.Error.Description, resp.Error.Code)
	}

	fmt.Printf("[%s] gRPC: Workspace/space opened successfully\n", time.Now().Format(time.RFC3339))
	return nil
}

// SyncMarkdownToAnyType creates or updates a page in AnyType from markdown
func (c *AnyTypeClient) SyncMarkdownToAnyType(ctx context.Context, change *FileChange, spaceID string) (string, error) {
	if c.conn == nil {
		return "", fmt.Errorf("not connected to AnyType")
	}

	fmt.Printf("[%s] gRPC: Creating/updating '%s' in AnyType\n", time.Now().Format(time.RFC3339), change.Title)

	// Create a new object (page) in the space with title and content
	objectID, err := c.createObject(ctx, change.Title, change.Content, spaceID)
	if err != nil {
		return "", fmt.Errorf("failed to create object: %w", err)
	}

	fmt.Printf("[%s] gRPC: Created/updated object '%s' successfully (ID: %s)\n", time.Now().Format(time.RFC3339), change.Title, objectID)
	return objectID, nil
}

// createObject invokes ObjectCreate RPC to create a new AnyType object
func (c *AnyTypeClient) createObject(ctx context.Context, title string, content string, spaceID string) (string, error) {
	fmt.Printf("[%s]   → Creating object: title='%s', content_len=%d bytes\n", time.Now().Format(time.RFC3339), title, len(content))

	// Create gRPC client stub
	client := service.NewClientCommandsClient(c.conn)

	// Add authentication to context
	ctx = c.withAuth(ctx)

	// Create details struct with title and content
	details := &types.Struct{
		Fields: map[string]*types.Value{
			"name": {
				Kind: &types.Value_StringValue{
					StringValue: title,
				},
			},
			"description": {
				Kind: &types.Value_StringValue{
					StringValue: content,
				},
			},
		},
	}

	// Create request with space ID and object details
	// Use "ot-note" as the object type (AnyType note type)
	req := &pb.RpcObjectCreateRequest{
		SpaceId:              spaceID,
		Details:              details,
		ObjectTypeUniqueKey:  "ot-note",
		InternalFlags:        nil,
	}

	// Call ObjectCreate RPC
	resp, err := client.ObjectCreate(ctx, req)
	if err != nil {
		return "", c.handleGRPCError(err)
	}

	// Check response error
	if resp.Error != nil && resp.Error.Code != pb.RpcObjectCreateResponseError_NULL {
		return "", fmt.Errorf("ObjectCreate failed: %s (%s)", resp.Error.Description, resp.Error.Code)
	}

	objectID := resp.ObjectId
	fmt.Printf("[%s]   → Created object ID: %s\n", time.Now().Format(time.RFC3339), objectID)
	return objectID, nil
}

// deleteObject invokes ObjectListDelete RPC to delete an AnyType object
func (c *AnyTypeClient) deleteObject(ctx context.Context, objectID string) error {
	fmt.Printf("[%s]   → Deleting object ID: %s\n", time.Now().Format(time.RFC3339), objectID)

	// Create gRPC client stub
	client := service.NewClientCommandsClient(c.conn)

	// Add authentication to context
	ctx = c.withAuth(ctx)

	// Create request to delete the object
	req := &pb.RpcObjectListDeleteRequest{
		ObjectIds: []string{objectID},
	}

	// Call ObjectListDelete RPC
	resp, err := client.ObjectListDelete(ctx, req)
	if err != nil {
		return c.handleGRPCError(err)
	}

	// Check response error
	if resp.Error != nil && resp.Error.Code != pb.RpcObjectListDeleteResponseError_NULL {
		return fmt.Errorf("ObjectListDelete failed: %s (%s)", resp.Error.Description, resp.Error.Code)
	}

	fmt.Printf("[%s]   → Successfully deleted object\n", time.Now().Format(time.RFC3339))
	return nil
}

// UploadImageWithID creates an image/file object in AnyType from binary data
// For now, wraps images in markdown notes (simpler approach)
func (c *AnyTypeClient) UploadImageWithID(ctx context.Context, filename string, data []byte, spaceID string) (string, error) {
	fmt.Printf("[%s] gRPC: Uploading image '%s' (%d bytes)\n", time.Now().Format(time.RFC3339), filename, len(data))

	// Create a markdown note documenting the image
	markdown := fmt.Sprintf(`# Image: %s

**Size:** %d bytes
**Uploaded:** %s

[Image file - %d bytes]
`, filename, len(data), time.Now().Format(time.RFC3339), len(data))

	// Create as markdown note
	change := &FileChange{
		Path:     fmt.Sprintf("/root/anytype-workspace/%s.md", filename),
		Filename: filename,
		Title:    fmt.Sprintf("Image: %s", filename),
		Content:  markdown,
	}

	objectID, err := c.SyncMarkdownWithID(ctx, change, spaceID)
	if err != nil {
		fmt.Printf("[%s] ✗ Image sync error for %s: %v\n", time.Now().Format(time.RFC3339), filename, err)
		return "", err
	}

	fmt.Printf("[%s] gRPC: Image '%s' uploaded successfully (ID: %s)\n", time.Now().Format(time.RFC3339), filename, objectID)
	return objectID, nil
}

// handleGRPCError provides detailed error messages for gRPC failures
func (c *AnyTypeClient) handleGRPCError(err error) error {
	if err == nil {
		return nil
	}

	st, ok := status.FromError(err)
	if !ok {
		return fmt.Errorf("unknown gRPC error: %w", err)
	}

	switch st.Code() {
	case codes.OK:
		return nil
	case codes.Unavailable:
		return fmt.Errorf("AnyType service unavailable - check if AnyType is running")
	case codes.DeadlineExceeded:
		return fmt.Errorf("gRPC call timeout")
	case codes.PermissionDenied:
		return fmt.Errorf("permission denied - check credentials or space access")
	case codes.NotFound:
		return fmt.Errorf("space or object not found")
	case codes.InvalidArgument:
		return fmt.Errorf("invalid request: %s", st.Message())
	case codes.Internal:
		return fmt.Errorf("AnyType internal error: %s", st.Message())
	case codes.Unauthenticated:
		return fmt.Errorf("not authenticated - check network membership")
	default:
		return fmt.Errorf("gRPC error %s: %s", st.Code(), st.Message())
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/metadata"
)

// AnyTypeClient wraps gRPC connection to AnyType
type AnyTypeClient struct {
	conn          *grpc.ClientConn
	addr          string
	sessionToken  string
	refreshMutex  sync.Mutex // Prevent concurrent token refreshes
	lastRefresh   time.Time  // Track when we last refreshed
	anytypeBinary string     // Path to anytype binary
}

// NewAnyTypeClient creates a new gRPC client for AnyType
func NewAnyTypeClient(addr string) (*AnyTypeClient, error) {
	client := &AnyTypeClient{
		addr:          addr,
		anytypeBinary: "/root/.local/bin/anytype", // Default path
	}

	// Read session token from config
	token, err := readSessionToken()
	if err != nil {
		fmt.Printf("Warning: failed to read session token: %v\n", err)
	} else {
		client.sessionToken = token
	}

	// Connect to gRPC server
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	conn, err := grpc.DialContext(
		ctx,
		addr,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithBlock(),
	)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to AnyType gRPC: %w", err)
	}

	client.conn = conn
	return client, nil
}

// withAuth adds authentication metadata to context
func (c *AnyTypeClient) withAuth(ctx context.Context) context.Context {
	if c.sessionToken != "" {
		return metadata.AppendToOutgoingContext(ctx, "token", c.sessionToken)
	}
	return ctx
}

// readSessionToken reads the session token from AnyType config
func readSessionToken() (string, error) {
	configPath := os.Getenv("HOME") + "/.anytype/config.json"

	data, err := os.ReadFile(configPath)
	if err != nil {
		return "", fmt.Errorf("failed to read config: %w", err)
	}

	var config struct {
		SessionToken string `json:"sessionToken"`
	}

	if err := json.Unmarshal(data, &config); err != nil {
		return "", fmt.Errorf("failed to parse config: %w", err)
	}

	return config.SessionToken, nil
}

// isAuthError checks if an error is an authentication error
func isAuthError(err error) bool {
	if err == nil {
		return false
	}
	errMsg := strings.ToLower(err.Error())
	return strings.Contains(errMsg, "not authenticated") ||
		strings.Contains(errMsg, "authentication failed") ||
		strings.Contains(errMsg, "invalid token") ||
		strings.Contains(errMsg, "session") ||
		strings.Contains(errMsg, "signature is invalid")
}

// refreshToken attempts to refresh the session token by restarting the anytype server
func (c *AnyTypeClient) refreshToken(ctx context.Context) error {
	c.refreshMutex.Lock()
	defer c.refreshMutex.Unlock()

	// Check if we recently refreshed (within last 30 seconds)
	// This prevents rapid refresh loops
	if time.Since(c.lastRefresh) < 30*time.Second {
		fmt.Printf("[%s] Token refresh attempted too soon, skipping\n", time.Now().Format(time.RFC3339))
		return fmt.Errorf("token refresh rate limit")
	}

	fmt.Printf("[%s] 🔄 Attempting to refresh session token...\n", time.Now().Format(time.RFC3339))

	// Step 1: Send SIGTERM to existing anytype serve process (graceful shutdown)
	fmt.Printf("[%s]   → Stopping anytype server...\n", time.Now().Format(time.RFC3339))
	killCmd := exec.Command("pkill", "-TERM", "-f", "anytype serve")
	if err := killCmd.Run(); err != nil {
		fmt.Printf("[%s]   ⚠ pkill returned: %v (may be normal)\n", time.Now().Format(time.RFC3339), err)
	}

	// Step 2: Wait for process to fully stop
	time.Sleep(3 * time.Second)

	// Step 3: Start anytype server in background
	fmt.Printf("[%s]   → Starting anytype server...\n", time.Now().Format(time.RFC3339))
	startCmd := exec.Command("nohup", c.anytypeBinary, "serve", "-q")

	// Redirect output to log file
	logFile, err := os.OpenFile("/tmp/anytype-serve.log", os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		return fmt.Errorf("failed to open log file: %w", err)
	}
	defer logFile.Close()

	startCmd.Stdout = logFile
	startCmd.Stderr = logFile

	if err := startCmd.Start(); err != nil {
		return fmt.Errorf("failed to start anytype server: %w", err)
	}

	// Step 4: Wait for server to initialize and generate new token
	fmt.Printf("[%s]   → Waiting for server to initialize...\n", time.Now().Format(time.RFC3339))
	time.Sleep(10 * time.Second)

	// Step 5: Verify server is up
	fmt.Printf("[%s]   → Verifying server is running...\n", time.Now().Format(time.RFC3339))

	// Step 5: Reload session token from config
	fmt.Printf("[%s]   → Reading new session token...\n", time.Now().Format(time.RFC3339))
	newToken, err := readSessionToken()
	if err != nil {
		return fmt.Errorf("failed to read new token: %w", err)
	}

	// Step 6: Update client's session token
	c.sessionToken = newToken
	c.lastRefresh = time.Now()

	// Step 7: Reconnect gRPC — the old connection died when anytype restarted
	fmt.Printf("[%s]   → Reconnecting gRPC to %s...\n", time.Now().Format(time.RFC3339), c.addr)
	if c.conn != nil {
		c.conn.Close()
	}
	connCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	newConn, err := grpc.DialContext(
		connCtx,
		c.addr,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithBlock(),
	)
	if err != nil {
		return fmt.Errorf("failed to reconnect gRPC after token refresh: %w", err)
	}
	c.conn = newConn

	fmt.Printf("[%s] ✓ Session token refreshed and gRPC reconnected\n", time.Now().Format(time.RFC3339))
	return nil
}

// withRetry wraps an operation with automatic token refresh on auth errors
func (c *AnyTypeClient) withRetry(ctx context.Context, operation func() error) error {
	err := operation()

	// If no error or not an auth error, return immediately
	if err == nil || !isAuthError(err) {
		return err
	}

	// Auth error detected - try to refresh token
	fmt.Printf("[%s] ⚠ Authentication error detected: %v\n", time.Now().Format(time.RFC3339), err)

	if refreshErr := c.refreshToken(ctx); refreshErr != nil {
		fmt.Printf("[%s] ✗ Token refresh failed: %v\n", time.Now().Format(time.RFC3339), refreshErr)
		return fmt.Errorf("auth error (token refresh failed): %w", err)
	}

	// Retry the operation with new token
	fmt.Printf("[%s] 🔁 Retrying operation with refreshed token...\n", time.Now().Format(time.RFC3339))
	err = operation()

	if err != nil {
		return fmt.Errorf("operation failed after token refresh: %w", err)
	}

	return nil
}

// SyncMarkdown syncs a markdown file to AnyType
func (c *AnyTypeClient) SyncMarkdown(ctx context.Context, change *FileChange, spaceID string) error {
	if c.conn == nil {
