	}

	fmt.Printf("[%s] gRPC: Syncing %s to space %s\n", time.Now().Format(time.RFC3339), change.Filename, spaceID)

	// Use the API layer to sync markdown to AnyType
	_, err := c.SyncMarkdownToAnyType(ctx, change, spaceID)
	return err
}

