  1→#!/usr/bin/env node
  2→/**
  3→ * AnyType Sync Script - Push markdown files to AnyType via HTTP API
  4→ * 
  5→ * Usage:
  6→ *   node sync-to-anytype.js <markdown-file> [--space <space-id>] [--api-url <url>] [--api-key <key>]
  7→ *   ANYTYPE_API_KEY=<key> ANYTYPE_SPACE_ID=<space-id> node sync-to-anytype.js <markdown-file>
  8→ *
  9→ * Environment variables:
 10→ *   ANYTYPE_API_KEY     - API key for AnyType (required)
 11→ *   ANYTYPE_SPACE_ID    - Space ID to sync to (required)
 12→ *   ANYTYPE_API_URL     - API URL (default: http://127.0.0.1:31012)
 13→ */
 14→
 15→const https = require('https');
 16→const http = require('http');
 17→const { URL } = require('url');
 18→const fs = require('fs');
 19→const path = require('path');
 20→
 21→// Configuration
 22→const CONFIG = {
 23→  apiUrl: process.env.ANYTYPE_API_URL || 'http://127.0.0.1:31012',
 24→  apiKey: process.env.ANYTYPE_API_KEY || '',
 25→  spaceId: process.env.ANYTYPE_SPACE_ID || '',
 26→  objectType: 'page'
 27→};
 28→
 29→class AnyTypeClient {
 30→  constructor(config = {}) {
 31→    this.apiUrl = config.apiUrl || CONFIG.apiUrl;
 32→    this.apiKey = config.apiKey || CONFIG.apiKey;
 33→    this.spaceId = config.spaceId || CONFIG.spaceId;
 34→    this.timeout = 30000;
 35→  }
 36→
 37→  async request(method, path, data = null) {
 38→    return new Promise((resolve, reject) => {
 39→      const url = new URL(path, this.apiUrl);
 40→      const isHttps = url.protocol === 'https:';
 41→      const httpLib = isHttps ? https : http;
 42→
 43→      const headers = {
 44→        'Authorization': `Bearer ${this.apiKey}`,
 45→        'Content-Type': 'application/json',
 46→        'User-Agent': 'OpenClaw-AnyType-Sync/1.0'
 47→      };
 48→
 49→      const options = { method, headers, timeout: this.timeout };
 50→
 51→      const req = httpLib.request(url, options, (res) => {
 52→        let body = '';
 53→        res.on('data', chunk => body += chunk);
 54→        res.on('end', () => {
 55→          let parsed;
 56→          try { parsed = body ? JSON.parse(body) : {}; } 
 57→          catch (e) { parsed = { raw: body }; }
 58→
 59→          if (res.statusCode >= 400) {
 60→            const error = new Error(`AnyType API error (${res.statusCode}): ${parsed.error || parsed.message || body}`);
 61→            error.statusCode = res.statusCode;
 62→            error.response = parsed;
 63→            reject(error);
 64→          } else {
 65→            resolve(parsed);
 66→          }
 67→        });
 68→      });
 69→
 70→      req.on('error', reject);
 71→      req.on('timeout', () => { req.abort(); reject(new Error(`Timeout (${this.timeout}ms)`)); });
 72→      if (data) req.write(JSON.stringify(data));
 73→      req.end();
 74→    });
 75→  }
 76→
 77→  async createObject({ typeKey = 'page', name, description = '', content = '' }) {
 78→    if (!this.spaceId) throw new Error('spaceId is required');
 79→
 80→    const data = {
 81→      type_key: typeKey,
 82→      name: name,
 83→      description: description,
 84→      snippet: content.substring(0, 500) // Preview text
 85→    };
 86→
 87→    return this.request('POST', 
 88→      `/v1/spaces/${this.spaceId}/objects`,
 89→      data
 90→    );
 91→  }
 92→
 93→  async listObjects() {
 94→    if (!this.spaceId) throw new Error('spaceId is required');
 95→    return this.request('GET', `/v1/spaces/${this.spaceId}/objects`);
 96→  }
 97→
 98→  async getTypes() {
 99→    if (!this.spaceId) throw new Error('spaceId is required');
100→    return this.request('GET', `/v1/spaces/${this.spaceId}/types`);
101→  }
102→}
103→
104→function parseMarkdown(filepath) {
105→  const content = fs.readFileSync(filepath, 'utf-8');
106→  const filename = path.basename(filepath, '.md');
107→  
108→  // Extract first heading as title
109→  let title = filename;
110→  const lines = content.split('\n');
111→  for (const line of lines) {
112→    if (line.startsWith('# ')) {
113→      title = line.substring(2).trim();
114→      break;
115→    }
116→    // Also check for title: or ---
117→    if (line.startsWith('title:')) {
118→      title = line.substring(6).trim();
119→      break;
120→    }
121→  }
122→
123→  return { title, content, filename };
124→}
125→
126→async function main() {
127→  const args = process.argv.slice(2);
128→  
129→  // Parse arguments
130→  let filepath = null;
131→  let spaceId = CONFIG.spaceId;
132→  let apiKey = CONFIG.apiKey;
133→  let apiUrl = CONFIG.apiUrl;
134→
135→  for (let i = 0; i < args.length; i++) {
136→    if (args[i] === '--space' && i + 1 < args.length) spaceId = args[++i];
137→    else if (args[i] === '--api-url' && i + 1 < args.length) apiUrl = args[++i];
138→    else if (args[i] === '--api-key' && i + 1 < args.length) apiKey = args[++i];
139→    else if (!args[i].startsWith('--')) filepath = args[i];
140→  }
141→
142→  // Validate
143→  if (!filepath) {
144→    console.error('Usage: node sync-to-anytype.js <markdown-file> [--space <id>] [--api-url <url>] [--api-key <key>]');
145→    process.exit(1);
146→  }
147→
148→  if (!apiKey) {
149→    console.error('ERROR: ANYTYPE_API_KEY is required');
150→    process.exit(1);
151→  }
152→
153→  if (!spaceId) {
154→    console.error('ERROR: ANYTYPE_SPACE_ID is required');
155→    process.exit(1);
156→  }
157→
158→  if (!fs.existsSync(filepath)) {
159→    console.error(`ERROR: File not found: ${filepath}`);
160→    process.exit(1);
161→  }
162→
163→  const client = new AnyTypeClient({ apiUrl, apiKey, spaceId });
164→
165→  // Parse markdown
166→  const { title, content, filename } = parseMarkdown(filepath);
167→  console.log(`📄 Syncing: ${filename}`);
168→  console.log(`   Title: ${title}`);
169→  console.log(`   Space: ${spaceId}`);
170→
171→  // Create object
172→  try {
173→    const result = await client.createObject({
174→      typeKey: 'page',
175→      name: title,
176→      content: content
177→    });
178→
179→    if (result.object) {
180→      console.log(`✅ Created: ${result.object.name}`);
181→      console.log(`   ID: ${result.object.id}`);
182→      return result.object;
183→    } else {
184→      console.log(`⚠️  Response:`, JSON.stringify(result).substring(0, 200));
185→      return result;
186→    }
187→  } catch (err) {
188→    console.error(`❌ Failed to sync: ${err.message}`);
189→    process.exit(1);
190→  }
191→}
192→
193→// Run
194→main().catch(err => {
195→  console.error('Fatal error:', err);
196→  process.exit(1);
197→});
