package main

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/fsnotify/fsnotify"
)

var (
	workspaceDir = os.ExpandEnv("$HOME/anytype-workspace")
	spaceID      = os.Getenv("ANYTYPE_SPACE_ID")
	grpcAddr     = "127.0.0.1:31010" // AnyType gRPC port from anytype serve
)

var (
	fileTimestamps = make(map[string]time.Time)
	debounceTime   = 2 * time.Second
	objectMap      *ObjectMap
)

// FileChange represents a markdown file change
type FileChange struct {
	Path     string
	Filename string
	Title    string
	Content  string
}

// ParseMarkdown extracts title and content from markdown file
func ParseMarkdown(filepath string) (*FileChange, error) {
	content, err := os.ReadFile(filepath)
	if err != nil {
		return nil, err
	}

	filename := strings.TrimSuffix(filepath[strings.LastIndex(filepath, "/")+1:], ".md")

	// Extract first heading as title
	title := filename
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "# ") {
			title = strings.TrimPrefix(line, "# ")
			break
		}
	}

	return &FileChange{
		Path:     filepath,
		Filename: filename,
		Title:    title,
		Content:  string(content),
	}, nil
}

// SyncFile processes a markdown file for sync
func SyncFile(ctx context.Context, client *AnyTypeClient, filepath string) (string, error) {
	change, err := ParseMarkdown(filepath)
	if err != nil {
		fmt.Printf("[%s] ✗ Error parsing %s: %v\n", time.Now().Format(time.RFC3339), filepath, err)
		return "", err
	}

	fmt.Printf("[%s] Syncing %s...\n", time.Now().Format(time.RFC3339), change.Filename)

	// Sync to AnyType via gRPC (if connected)
	if client == nil {
		fmt.Printf("[%s] ⚠ %s queued (gRPC client not connected)\n", time.Now().Format(time.RFC3339), change.Filename)
		return "", fmt.Errorf("client not connected")
	}

	// Get object ID from the sync operation
	objectID, err := client.SyncMarkdownWithID(ctx, change, spaceID)
	if err != nil {
		fmt.Printf("[%s] ✗ Sync error for %s: %v\n", time.Now().Format(time.RFC3339), change.Filename, err)
		return "", err
	}

	// Store the object ID mapping
	if objectMap != nil {
		if err := objectMap.Set(change.Filename, objectID); err != nil {
			fmt.Printf("[%s] ⚠ Failed to save object mapping: %v\n", time.Now().Format(time.RFC3339), err)
		}
	}

	fmt.Printf("[%s] ✓ %s synced to AnyType\n", time.Now().Format(time.RFC3339), change.Filename)
	return objectID, nil
}

// SyncImage processes an image file for sync
func SyncImage(ctx context.Context, client *AnyTypeClient, filepath string) (string, error) {
	// Read the image file
	data, err := os.ReadFile(filepath)
	if err != nil {
		fmt.Printf("[%s] ✗ Error reading image %s: %v\n", time.Now().Format(time.RFC3339), filepath, err)
		return "", err
	}

	// Extract filename without extension
	filename := filepath[strings.LastIndex(filepath, "/")+1:]
	name := filename
	if idx := strings.LastIndex(name, "."); idx != -1 {
		name = name[:idx]
	}

	fmt.Printf("[%s] Syncing image %s... (%d bytes)\n", time.Now().Format(time.RFC3339), name, len(data))

	// Sync to AnyType via gRPC (if connected)
	if client == nil {
		fmt.Printf("[%s] ⚠ %s queued (gRPC client not connected)\n", time.Now().Format(time.RFC3339), name)
		return "", fmt.Errorf("client not connected")
	}

	// Upload image as a file object
	objectID, err := client.UploadImageWithID(ctx, name, data, spaceID)
	if err != nil {
		fmt.Printf("[%s] ✗ Image sync error for %s: %v\n", time.Now().Format(time.RFC3339), name, err)
		return "", err
	}

	// Store the object ID mapping
	if objectMap != nil {
		if err := objectMap.Set(name, objectID); err != nil {
			fmt.Printf("[%s] ⚠ Failed to save object mapping: %v\n", time.Now().Format(time.RFC3339), err)
		}
	}

	fmt.Printf("[%s] ✓ %s synced to AnyType (ID: %s)\n", time.Now().Format(time.RFC3339), name, objectID)
	return objectID, nil
}

// DeleteFile processes a markdown file deletion
func DeleteFile(ctx context.Context, client *AnyTypeClient, filepath string) {
	filename := strings.TrimSuffix(filepath[strings.LastIndex(filepath, "/")+1:], ".md")

	fmt.Printf("[%s] Deleting %s...\n", time.Now().Format(time.RFC3339), filename)

	// Delete from AnyType via gRPC (if connected)
	if client == nil {
		fmt.Printf("[%s] ⚠ %s delete queued (gRPC client not connected)\n", time.Now().Format(time.RFC3339), filename)
		return
	}

	// Get object ID from mapping
	if objectMap == nil {
		fmt.Printf("[%s] ✗ Object map not initialized\n", time.Now().Format(time.RFC3339))
		return
	}

	objectID, exists := objectMap.Get(filename)
	if !exists {
		fmt.Printf("[%s] ⚠ No object ID found for %s (may have been deleted already)\n", time.Now().Format(time.RFC3339), filename)
		return
	}

	if err := client.DeleteMarkdown(ctx, objectID); err != nil {
		fmt.Printf("[%s] ✗ Delete error for %s: %v\n", time.Now().Format(time.RFC3339), filename, err)
		return
	}

	// Remove from object map
	if err := objectMap.Delete(filename); err != nil {
		fmt.Printf("[%s] ⚠ Failed to update object mapping: %v\n", time.Now().Format(time.RFC3339), err)
	}

	fmt.Printf("[%s] ✓ %s deleted from AnyType\n", time.Now().Format(time.RFC3339), filename)
}

// WatchDirectory monitors for markdown file changes
func WatchDirectory(ctx context.Context, dir string, client *AnyTypeClient, watcher *fsnotify.Watcher) error {
	// Add root directory
	if err := watcher.Add(dir); err != nil {
		return err
	}

	// Add subdirectories
	filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() && path != dir {
			watcher.Add(path)
		}
		return nil
	})

	fmt.Printf("[%s] Watching %s for changes...\n", time.Now().Format(time.RFC3339), dir)

	for {
		select {
		case event, ok := <-watcher.Events:
			if !ok {
				return nil
			}

	// Only process .md, image, or PDF files
			isMarkdown := strings.HasSuffix(event.Name, ".md")
			isImage := strings.HasSuffix(event.Name, ".jpg") || 
					strings.HasSuffix(event.Name, ".jpeg") ||
					strings.HasSuffix(event.Name, ".png") || 
					strings.HasSuffix(event.Name, ".gif") ||
					strings.HasSuffix(event.Name, ".webp")
			isPDF := strings.HasSuffix(event.Name, ".pdf")

			if !isMarkdown && !isImage && !isPDF {
				continue
			}

			// Check if event is recent (debounce)
			now := time.Now()
			if lastChange, exists := fileTimestamps[event.Name]; exists {
				if now.Sub(lastChange) < debounceTime {
					continue
				}
			}
			fileTimestamps[event.Name] = now

// Handle different event types
			if event.Op&fsnotify.Remove == fsnotify.Remove {
				// File was deleted
				filename := event.Name[strings.LastIndex(event.Name, "/")+1:]
				if idx := strings.LastIndex(filename, "."); idx != -1 {
					filename = filename[:idx]
				}
				DeleteFile(ctx, client, event.Name)
			} else {
				// Wait for file to stabilize
				time.Sleep(debounceTime)

// Check if file still exists (for create/write events)
				if _, err := os.Stat(event.Name); err == nil {
					if isMarkdown {
						SyncFile(ctx, client, event.Name)
					} else if isImage || isPDF {
						SyncImage(ctx, client, event.Name)
					}
				}
			}

		case err, ok := <-watcher.Errors:
			if !ok {
				return nil
			}
			fmt.Printf("[%s] Watcher error: %v\n", time.Now().Format(time.RFC3339), err)
		}
	}
}

// InitialSync syncs all existing markdown files
func InitialSync(ctx context.Context, dir string, client *AnyTypeClient) error {
	fmt.Printf("[%s] Running initial sync...\n", time.Now().Format(time.RFC3339))

	files, err := os.ReadDir(dir)
	if err != nil {
		return err
	}

for _, file := range files {
		if file.IsDir() {
			continue
		}

		filename := file.Name()
		fullPath := filepath.Join(dir, filename)

		if strings.HasSuffix(filename, ".md") {
			SyncFile(ctx, client, fullPath)
		} else if strings.HasSuffix(filename, ".jpg") || strings.HasSuffix(filename, ".jpeg") ||
			strings.HasSuffix(filename, ".png") || strings.HasSuffix(filename, ".gif") ||
			strings.HasSuffix(filename, ".webp") || strings.HasSuffix(filename, ".pdf") {
			SyncImage(ctx, client, fullPath)
		}
	}

	fmt.Printf("[%s] Initial sync complete\n", time.Now().Format(time.RFC3339))
	return nil
}

func main() {
	ctx := context.Background()

	// Initialize object map
	var err error
	objectMap, err = NewObjectMap()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to initialize object map: %v\n", err)
		os.Exit(1)
	}

	// Check workspace directory exists, create if not
	if _, err := os.Stat(workspaceDir); os.IsNotExist(err) {
		fmt.Printf("[%s] Creating workspace directory: %s\n", time.Now().Format(time.RFC3339), workspaceDir)
		if err := os.MkdirAll(workspaceDir, 0755); err != nil {
			fmt.Fprintf(os.Stderr, "Error: failed to create %s: %v\n", workspaceDir, err)
			os.Exit(1)
		}
	}

	// Validate space ID
	if spaceID == "" {
		fmt.Fprintf(os.Stderr, "Error: ANYTYPE_SPACE_ID environment variable is required\n")
		os.Exit(1)
	}

	// Create file watcher
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to create watcher: %v\n", err)
		os.Exit(1)
	}
	defer watcher.Close()

	// Connect to AnyType gRPC (optional - continue if connection fails)
	fmt.Printf("[%s] Connecting to AnyType at %s...\n", time.Now().Format(time.RFC3339), grpcAddr)
	client, err := NewAnyTypeClient(grpcAddr)
	if err != nil {
		fmt.Printf("[%s] WARNING: Failed to connect to AnyType: %v\n", time.Now().Format(time.RFC3339), err)
		fmt.Printf("[%s] Watcher will run but sync will be disabled until connection succeeds\n", time.Now().Format(time.RFC3339))
		client = nil
	} else {
		defer client.Close()
		fmt.Printf("[%s] Connected to AnyType\n", time.Now().Format(time.RFC3339))

		// Health check
		if err := client.HealthCheck(ctx); err != nil {
			fmt.Printf("[%s] WARNING: Health check failed: %v\n", time.Now().Format(time.RFC3339), err)
		}

		// Open the space so we can create objects in it
		fmt.Printf("[%s] Opening space %s...\n", time.Now().Format(time.RFC3339), spaceID)
		if err := client.OpenSpace(ctx, spaceID); err != nil {
			fmt.Printf("[%s] WARNING: Failed to open space: %v\n", time.Now().Format(time.RFC3339), err)
			fmt.Printf("[%s] Will continue but sync may fail\n", time.Now().Format(time.RFC3339))
		}
	}

	// Initial sync
	if err := InitialSync(ctx, workspaceDir, client); err != nil {
		fmt.Fprintf(os.Stderr, "Initial sync failed: %v\n", err)
		os.Exit(1)
	}

	// Start watching
	if err := WatchDirectory(ctx, workspaceDir, client, watcher); err != nil {
		fmt.Fprintf(os.Stderr, "Watch failed: %v\n", err)
		os.Exit(1)
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

var objectMapFile = os.ExpandEnv("$HOME/.anytype-workspace-objectmap.json")

// ObjectMap tracks the mapping between filenames and AnyType object IDs
type ObjectMap struct {
	mu      sync.RWMutex
	mapping map[string]string // filename -> objectID
}

// NewObjectMap creates a new object map and loads existing mappings
func NewObjectMap() (*ObjectMap, error) {
	om := &ObjectMap{
		mapping: make(map[string]string),
	}

	// Try to load existing mappings
	if err := om.load(); err != nil {
		// If file doesn't exist, that's ok
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("failed to load object map: %w", err)
		}
	}

	return om, nil
}

// Set stores a filename -> objectID mapping
func (om *ObjectMap) Set(filename, objectID string) error {
	om.mu.Lock()
	defer om.mu.Unlock()

	om.mapping[filename] = objectID
	return om.save()
}

// Get retrieves the objectID for a filename
func (om *ObjectMap) Get(filename string) (string, bool) {
	om.mu.RLock()
	defer om.mu.RUnlock()

	objectID, exists := om.mapping[filename]
	return objectID, exists
}

// Delete removes a filename mapping
func (om *ObjectMap) Delete(filename string) error {
	om.mu.Lock()
	defer om.mu.Unlock()

	delete(om.mapping, filename)
	return om.save()
}

// load reads the object map from disk
func (om *ObjectMap) load() error {
	data, err := os.ReadFile(objectMapFile)
	if err != nil {
		return err
	}

	return json.Unmarshal(data, &om.mapping)
}

// save writes the object map to disk
func (om *ObjectMap) save() error {
	data, err := json.MarshalIndent(om.mapping, "", "  ")
	if err != nil {
		return err
	}

	// Ensure directory exists
	dir := filepath.Dir(objectMapFile)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	return os.WriteFile(objectMapFile, data, 0644)
}
